let body="";
if(page==="home")body="<main><section class=\"hero hero-copy\"><div><p class=\"eyebrow\">"+t[0]+"</p><h1>"+t[1]+"</h1><p class=\"lead\">"+t[2]+"</p>"+search()+"<p class=\"micro\">Research first. Check the listing, selected variant and current shipping information before any transaction.</p></div></section><section class=\"section\"><p class=\"eyebrow\">01 — RESEARCH PATHS</p><div class=\"paths\"><a href=\""+q("spreadsheet.html")+"\"><b>"+t[7]+"</b><span>Category paths & search terms</span></a><a href=\""+q("how-to-buy.html")+"\"><b>"+t[8]+"</b><span>Order-flow questions to verify</span></a><a href=\""+q("news.html")+"\"><b>"+t[9]+"</b><span>QC, parcel & tracking research</span></a></div></section><section class=\"section\"><p class=\"eyebrow\">02 — "+t[10]+"</p><h2>"+t[13]+"</h2><p class=\"copy\">"+t[14]+"</p>"+cards()+"</section><section class=\"section region\"><p class=\"eyebrow\">03 — MARKETS</p><h2>"+t[23]+"</h2><p class=\"copy\">"+t[24]+"</p></section></main>";
else if(page==="categories")body="<main class=\"page\"><p class=\"eyebrow\">JOYACELL / "+t[10]+"</p><h1>"+t[13]+"</h1><p class=\"lead\">"+t[14]+"</p>"+cards()+"</main>";
else if(page==="howto")body="<main class=\"page\"><p class=\"eyebrow\">JOYACELL / "+t[8]+"</p><h1>"+t[15]+"</h1><p class=\"lead\">"+t[16]+"</p><ol><li><b>01</b><div><h3>"+t[7]+"</h3><p>Use a focused term or category to narrow a broad catalogue.</p></div></li><li><b>02</b><div><h3>"+t[11]+"</h3><p>Read the listing, variant and images before treating any card as a final decision.</p></div></li><li><b>03</b><div><h3>QC & parcel</h3><p>Use the current official order flow for the actual QC, payment and shipping steps.</p></div></li></ol><aside><b>Important</b><p>Prices, availability, QC outcomes, tax, carrier acceptance and delivery timing need to be checked in the live order flow. Joyacell does not promise them.</p></aside></main>";
else if(page==="news")body="<main class=\"page\"><p class=\"eyebrow\">JOYACELL / "+t[9]+"</p><h1>"+t[17]+"</h1><p class=\"lead\">"+t[18]+"</p><article><p class=\"eyebrow\">RESEARCH NOTE · SEPTEMBER 2026</p><h2>Check a parcel from the listing outward</h2><p>Start with stable details: listing description, selected size or colour, seller images and product link. This makes it easier to recognise the right item later.</p><p>Warehouse QC is a later check, not a substitute for reading the listing. Compare a received item with the selected variant and decide what matters to you.</p><p>Shipping cost can depend on the packed parcel, not product price alone. Weight, dimensions, route rules and carrier measurement can change the final basis. Never treat an estimate as a fixed cost or delivery time.</p></article></main>";
else if(page==="details")body="<main class=\"page\"><p class=\"eyebrow\">JOYACELL / "+t[11]+"</p><h1>"+t[19]+"</h1><p class=\"lead\">"+t[20]+"</p><div class=\"check\">"+["Product title and link match the intended result.","Selected colour, size and variation are recorded.","Seller images and description are compared.","QC review is kept separate from the listing judgement.","Packed parcel details are reviewed before shipping."].map((x,i)=>"<p><b>0"+(i+1)+"</b>"+x+"</p>").join("")+"</div><a class=\"button\" href=\""+find("joyagoo product details")+"\">"+t[4]+"</a></main>";
else if(page==="faq")body="<main class=\"page\"><p class=\"eyebrow\">JOYACELL / "+t[12]+"</p><h1>"+t[21]+"</h1><p class=\"lead\">"+t[22]+"</p><div class=\"faq\">"+[["What does Joyacell do?","It organises research, product discovery and verification questions before a user continues elsewhere."],["Can I pay or place an order here?","No. Joyacell does not provide checkout, wallet, warehouse or shipping actions."],["Does a product card guarantee quality?","No. A product card is a starting point; check the live listing and any official QC process."],["Are shipping times or costs guaranteed?","No. They can vary by packed parcel, route, carrier rules and current conditions."],["Where does search go?","The search form and database buttons send the entered term to FindSpreadsheet."]].map(x=>"<details><summary>"+x[0]+"</summary><p>"+x[1]+"</p></details>").join("")+"</div></main>";
else body="<main class=\"page\"><p class=\"eyebrow\">JOYACELL / "+t[7]+"</p><h1>"+t[7]+": find a shorter path through a broad catalogue</h1><p class=\"lead\">A spreadsheet is useful when it reduces browsing friction without replacing careful review. Use search terms, category paths and source information to make a smaller shortlist.</p>"+search()+"<section class=\"split\"><div><h2>Use it for discovery</h2><p>Search by product type, material or style; use categories when the first search is too broad; keep details with the link you plan to review.</p></div><div><h2>Not a promise</h2><p>Listings can change. A spreadsheet cannot guarantee availability, price, quality, route eligibility or delivery time.</p></div></section><a class=\"button\" href=\""+q("categories.html")+"\">"+t[10]+"</a></main>";
const roleBlock="<section class=\"roles\"><p class=\"eyebrow\">04 — CLEAR RESPONSIBILITIES</p><div class=\"role-grid\"><article><span>JOYACELL</span><h2>Find, compare, preview and learn.</h2><p>Joyacell helps you find products, browse focused categories, review visual context and read independent guides before choosing a next step.</p></article><article><span>JOYAGOO OFFICIAL PLATFORM</span><h2>Account, payment, warehouse QC and shipping.</h2><p>Joyagoo’s official order flow is where account actions, payment, warehouse QC confirmation and parcel shipping are handled.</p></article></div></section>";
